<section class="panel"><div class="panel-heading"><div><span class="eyebrow">KANITA DAYALI İNCELEME</span><h2>Kriter bazlı bulgular</h2><p>Başlığı açarak metin kanıtını ve inceleme önerisini görün.</p></div><span class="count-label">8 kontrol</span></div><div class="criteria-list"><?php foreach($r['criteria'] as $key=>$c): ?><details class="criterion" <?= $c['status']!=='found'?'open':'' ?>><summary><span class="criterion-number"><?= sprintf('%02d',array_search($key,array_keys($r['criteria']))+1) ?></span><span class="criterion-title"><strong><?= e($c['title']) ?></strong><small><?= e($c['basis']) ?> · <?= e($c['kind']) ?></small></span><?= badge($c['status']) ?><span class="chevron">⌄</span></summary><div class="criterion-body"><?php if($c['evidence']): ?><h3>Metinde eşleşen cümleler</h3><?php foreach($c['evidence'] as $sentence): ?><blockquote><?= e($sentence) ?></blockquote><?php endforeach;else: ?><p class="muted">Bu kritere ait örüntülerle eşleşen bir cümle bulunamadı.</p><?php endif ?><?php if(!empty($c['issues'])): ?><ul class="criterion-issues"><?php foreach($c['issues'] as $issue): ?><li><?= e($issue) ?></li><?php endforeach ?></ul><?php endif ?><div class="recommendation"><strong>İnceleme önerisi</strong><p><?= e($c['advice']) ?></p></div><small class="muted"><?= (int)$c['matched_groups'] ?> / <?= (int)$c['total_groups'] ?> örüntü grubu eşleşti. <?= $c['weight']?'Skor ağırlığı: %'.(int)$c['weight'].'.':'Tamamlayıcı kontrol; skora dahil değil.' ?></small></div></details><?php endforeach ?></div></section>
<section class="panel"><div class="panel-heading"><div><h2>Uzman değerlendirmeleri</h2><p>Otomatik sonuçtan bağımsız, gerekçeli insan değerlendirmeleri.</p></div><?php if(!$isGuest && expert($u)): ?><a class="button secondary" href="<?= url('review',['id'=>$a['id']]) ?>">İncele <?= icon('arrow') ?></a><?php endif ?></div><?php if(!$reviews): ?><div class="empty compact"><p><?= $isGuest?'Uzman değerlendirmesi için raporu hesabınıza kaydedin.':'Henüz uzman değerlendirmesi eklenmedi.' ?></p></div><?php else: ?><div class="review-notes"><?php foreach($reviews as $review): ?><article><div><strong><?= e(Analyzer::criteria()[$review['criterion']]['title']) ?></strong><span class="badge <?= $review['verdict']==='sufficient'?'found':($review['verdict']==='uncertain'?'partial':'missing') ?>"><?= e(['sufficient'=>'Yeterli','insufficient'=>'Yetersiz','uncertain'=>'Belirsiz'][$review['verdict']]) ?></span></div><p><?= nl2br(e($review['note'])) ?></p><small class="muted"><?= e($review['expert']) ?> · <?= date('d.m.Y H:i',strtotime($review['updated_at'])) ?></small></article><?php endforeach ?></div><?php endif ?></section>
